'use strict';

// Inspect the real blog generated by npm test (or existing output when debugging). Assertions follow current
// declarations, not the authors, timestamps or inventory of a past migration.
const assert = require('node:assert/strict');
const { test } = require('node:test');
const fs = require('node:fs');
const path = require('node:path');
const { pageMetadata } = require('./helpers/html');
const { verifyBlogContent } = require('./helpers/blog-content');
const { withSite } = require('./helpers/site');

const site = path.resolve(__dirname, '..');
test("current blog metadata, feed and future/draft declarations", () => {
  const { config, posts } = verifyBlogContent(site);
  for (const route of [
    "index.html",
    "about/index.html",
    "archives/index.html",
    "tags/index.html",
    "categories/index.html",
  ]) {
    const url = config.url + "/" + route.replace(/index\.html$/, "");
    const doc = pageMetadata(
      fs.readFileSync(path.join(site, "public", route), "utf8"),
      url,
      "zh-CN",
    );
    if (route === "about/index.html") {
      assert.equal(doc.text(doc.tags("h1")[0]), "About");
      assert.equal(
        doc.attrs(doc.tags("h1")[0].parentNode).class,
        "content",
        "About H1 is rendered from source Markdown",
      );
      assert.deepEqual(doc.meta("og:title"), ["关于"]);
      assert.equal(doc.text(doc.tags("title")[0]), `关于 | ${config.title}`);
    }
  }

  // An unlimited real-content feed checks older articles too. Add new articles
  // without extending any historical inventory, slug plan or redirect map.
  const files = {};
  for (const file of fs.readdirSync(
    path.join(__dirname, "fixture/source/_posts"),
  ))
    files["source/_posts/" + file] = null;
  for (const post of posts)
    files["source/" + post.source] = fs.readFileSync(
      path.join(site, "source", post.source),
      "utf8",
    );
  const article = (fields) =>
    `---\ntitle: New article\ndate: 2099-01-01 08:00:00\ndescription: An independent description of this new article.\n${fields}---\n\n## Body\n\nNew content.\n`;
  files["source/_posts/new-default.md"] = article("");
  files["source/_posts/new-reprint.md"] = article(
    'author: " Guest Writer "\nsource_url: https://example.net/original/\nupdated: 2099-02-01 08:00:00\n',
  );
  files["source/_posts/new-anonymous.md"] = article("author: false\n");
  files["source/_posts/unpublished.md"] = article("published: false\n");
  files["source/_drafts/new-draft.md"] = article("");
  withSite(
    {
      blogScripts: true,
      config: {
        url: config.url,
        language: config.language,
        author: config.author,
        timezone: config.timezone,
        future: true,
        render_drafts: false,
        updated_option: "empty",
        feed: { type: "atom", path: "atom.xml", limit: 0 },
      },
      files,
    },
    (dir, result) => {
      assert.equal(result.status, 0, result.stdout + result.stderr);
      const current = verifyBlogContent(dir);
      assert.equal(
        current.posts.length,
        posts.length + 3,
        "new articles publish without changing migration evidence; drafts and unpublished posts stay out",
      );
    },
  );
});
